events.onValueChange:
function(form) {
  form.get('OutReach_Text').setHidden(true);
  form.get('Phulwari_Text').setHidden(true);
  if (form.get('Location of Visit').getValue() === 'Phulwari') {
    form.get('OutReach_Text').setHidden(true);
    form.get('Phulwari_Text').setHidden(false);
  } else {

  }
  if (form.get('Location of Visit').getValue() === 'OutReach') {
    form.get('Phulwari_Text').setHidden(true);
    form.get('OutReach_Text').setHidden(false);
  } else {}
  if (form.get('Location of Visit').getValue() === 'Clinic') {
    form.get('Phulwari_Text').setHidden(true);
    form.get('OutReach_Text').setHidden(true);
  } else {}
  if (form.get('Location of Visit').getValue() === 'Home') {
    form.get('Phulwari_Text').setHidden(true);
    form.get('OutReach_Text').setHidden(true);
  } else {}
}

function(form) {
  var multi_select = form.get('TB_Intake_Any_Other_Diagnosis').currentRecord.value.value;
  var length = multi_select == undefined ? 0 : multi_select.length;
  var arr = []
  if (length == 0) {
    form.get("TB_Intake_other_diagnosis").setHidden(true);
  } else {
    for (var i = 0; i < length; i++) {
      var name = multi_select[i].displayString == undefined ? multi_select[i].name : multi_select[i].displayString;
      arr.push(name);
      if (arr.includes('Other_Diagnosis'))
        form.get("TB_Intake_other_diagnosis").setHidden(false);
      else
        form.get("TB_Intake_other_diagnosis").setHidden(true);
    }
  }
}

function(form) {
  if (form.get('Subscription card').getValue() === 'Yes') {
    form.get('Subscription card Numbers').setHidden(false);
  } else {
    form.get('Subscription card Numbers').setHidden(true);
  }
}
